<div class="section-head"><div><span class="eyebrow">Ask clarification</span><h2>Contest questions</h2><p class="muted">Questions must relate to a contest statement or rule.</p></div></div><section class="grid grid-2"><form class="card grid" method="post" action="<?=e(url('/clarifications'))?>"><?=csrf_field()?><h2>Ask a question</h2><div class="field"><label for="contest_id">Contest</label><select id="contest_id" name="contest_id"><?php foreach($contests as $c):?><option value="<?=e($c['contest_id'])?>"><?=e($c['contest_title'])?></option><?php endforeach;?></select></div><div class="field"><div class="section-head"><label for="question">Question</label><span id="question-count" class="help"></span></div><textarea id="question" name="question" maxlength="1000" data-count="question-count" required></textarea></div><button class="button">Submit question</button></form>
<div class="grid"><article class="card"><h2>Previous clarifications</h2><?php foreach($clarifications as $cl):?><div class="card"><div class="section-head"><strong><?=e($cl['question'])?></strong><span class="badge badge-<?=e(strtolower($cl['clarification_status']))?>"><?=e($cl['clarification_status'])?></span></div><small class="muted"><?=e($cl['contest_title'])?> · <?=e($cl['asked_at'])?></small><?php if($cl['answer']):?><p><strong>Answer:</strong> <?=e($cl['answer'])?></p><?php endif;?></div><?php endforeach;?><?php if(!$clarifications):?><p class="empty">No clarifications yet.</p><?php endif;?></article></div></section>
